ALLOWED_MODELS = {"veo3.1", "veo3.1-pro", "seedance-1.5-pro", "grok-video-3", "sora2"}
SIZE_RE = re.compile(r"^\d+x\d+$")
MODEL_DURATION = {
    "grok-video-3": {6, 10, 15},
    "sora2": {10, 15},
    "seedance-1.5-pro": {4, 5, 6, 7, 8, 9, 10, 11, 12},
}


def fail(error, output=None):
    print(json.dumps({"success": False, "error": error, "output": output if output is not None else ""}, ensure_ascii=False))
    sys.exit(0)


def parse_payload(raw):
    try:
        data = json.loads(raw)
    except Exception as e:
        fail("Invalid JSON payload", {"payload": raw, "exception": str(e)})
    if not isinstance(data, dict):
        fail("Payload must be a JSON object", {"payload": data})
    return data


def request(method, url, payload=None):
    if not API_KEY:
        fail("VECTCUT_API_KEY is required")
    body = None if payload is None else json.dumps(payload, ensure_ascii=False).encode("utf-8")
    headers = {"Authorization": f"Bearer {API_KEY}", "Content-Type": "application/json"}
    req = urllib.request.Request(url=url, data=body, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req) as resp:
            text = resp.read().decode("utf-8", errors="replace")
            status = resp.status
    except urllib.error.HTTPError as e:
        fail(f"HTTP error: {e.code}", {"raw_response": e.read().decode("utf-8", errors="replace")})
    except urllib.error.URLError as e:
        fail("Network error", {"reason": str(e.reason)})
    if status < 200 or status >= 300:
        fail(f"HTTP non-2xx: {status}", {"raw_response": text})
    try:
        data = json.loads(text)
    except Exception:
        fail("Response is not valid JSON", {"raw_response": text})
    return data


def validate_generate(payload):
    for key in ["prompt", "model", "resolution"]:
        if not isinstance(payload.get(key), str) or not payload.get(key).strip():
            fail(f"{key} is required")
    model = payload["model"]
    if model not in ALLOWED_MODELS:
        fail("model must be one of: veo3.1, veo3.1-pro, seedance-1.5-pro, grok-video-3, sora2")
    if not SIZE_RE.match(payload["resolution"]):
        fail("resolution must match format: <width>x<height>")
    if "reference_image" in payload:
        ref = payload["reference_image"]
        if isinstance(ref, str):
            if not ref.startswith(("http://", "https://")):
                fail("reference_image must start with http:// or https://")
        elif isinstance(ref, list):
            if not ref:
                fail("reference_image array cannot be empty")
            for u in ref:
                if not isinstance(u, str) or not u.startswith(("http://", "https://")):
                    fail("reference_image array must contain valid urls")
        else:
            fail("reference_image must be a string or array<string>")
    if "end_image" in payload:
        end_image = payload["end_image"]
        if not isinstance(end_image, str) or not end_image.startswith(("http://", "https://")):
            fail("end_image must start with http:// or https://")
        if model not in {"veo3.1", "veo3.1-pro", "seedance-1.5-pro"}:
            fail(f"model {model} does not support end_image")
    if "gen_duration" in payload:
        if not isinstance(payload["gen_duration"], int):
            fail("gen_duration must be an integer")
        allowed = MODEL_DURATION.get(model)
        if not allowed:
            fail(f"model {model} does not support gen_duration")
        if payload["gen_duration"] not in allowed:
            fail(f"gen_duration for {model} must be one of: {sorted(allowed)}")


def validate_status(payload):
    if not isinstance(payload.get("task_id"), str) or not payload.get("task_id").strip():
        fail("task_id is required")


def run_generate(payload):
    validate_generate(payload)
    data = request("POST", f"{BASE_URL.rstrip('/')}/generate_ai_video", payload)
    if isinstance(data, dict):
        task_id = data.get("task_id")
        if not task_id and isinstance(data.get("output"), dict):
            task_id = data["output"].get("task_id")
        if not task_id:
            fail("Missing key field: task_id", {"response": data})
    else:
        fail("JSON response must be an object", {"response": data})
    print(json.dumps(data, ensure_ascii=False))


def run_status(payload):
    validate_status(payload)
    qs = urllib.parse.urlencode({"task_id": payload["task_id"]})
    data = request("GET", f"{BASE_URL.rstrip('/')}/aivideo/task_status?{qs}")
    if not isinstance(data, dict):
        fail("JSON response must be an object", {"response": data})
    status = str(data.get("status", "")).lower()
    if status == "completed" and not data.get("video_url"):
        fail("Missing key field: video_url", {"response": data})
    print(json.dumps(data, ensure_ascii=False))


def main():
    if len(sys.argv) < 3:
        print(f"Usage: {sys.argv[0]} <generate_ai_video|ai_video_task_status> '<json_payload>'")
        sys.exit(1)
    action = sys.argv[1]
    payload = parse_payload(sys.argv[2])
    if action == "generate_ai_video":
        run_generate(payload)
        return
    if action == "ai_video_task_status":
        run_status(payload)
        return
    print(f"Usage: {sys.argv[0]} <generate_ai_video|ai_video_task_status> '<json_payload>'")
    sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE_URL = os.getenv("VECTCUT_BASE_URL", "https://open.vectcut.com/cut_jianying")
API_KEY = os.getenv("VECTCUT_API_KEY", "")
ALLOWED_PROVIDERS = {"azure", "volc", "minimax", "fish"}
MINIMAX_MODELS = {"speech-2.6-turbo", "speech-2.6-hd"}
CLONE_URL = os.getenv("VECTCUT_LLM_BASE_URL", "https://open.vectcut.com/llm")


def fail(error, output=None):
    print(json.dumps({"success": False, "error": error, "output": output if output is not None else ""}, ensure_ascii=False))
    sys.exit(0)


def parse_payload(raw):
    try:
        data = json.loads(raw)
    except Exception as e:
        fail("Invalid JSON payload", {"payload": raw, "exception": str(e)})
    if not isinstance(data, dict):
        fail("Payload must be a JSON object", {"payload": data})
    return data


def request_get(url):
    if not API_KEY:
        fail("VECTCUT_API_KEY is required")
    req = urllib.request.Request(url=url, method="GET", headers={"Authorization": f"Bearer {API_KEY}"})
    try:
        with urllib.request.urlopen(req) as resp:
            text = resp.read().decode("utf-8", errors="replace")
            status = resp.status
    except urllib.error.HTTPError as e:
        fail(f"HTTP error: {e.code}", {"raw_response": e.read().decode("utf-8", errors="replace")})
    except urllib.error.URLError as e:
        fail("Network error", {"reason": str(e.reason)})
    if status < 200 or status >= 300:
        fail(f"HTTP non-2xx: {status}", {"raw_response": text})
    try:
        data = json.loads(text)
    except Exception:
        fail("Response is not valid JSON", {"raw_response": text})
    return data


def validate_generate_payload(payload):
    required = ["text", "provider", "voice_id"]
    for key in required:
        v = payload.get(key)
        if not isinstance(v, str) or not v.strip():
            fail(f"{key} is required")

    provider = payload.get("provider")
    if provider not in ALLOWED_PROVIDERS:
        fail("provider must be one of: azure, volc, minimax, fish")

    model = payload.get("model")
    if provider == "minimax":
        if not isinstance(model, str) or not model.strip():
            fail("model is required when provider=minimax")
        if model not in MINIMAX_MODELS:
            fail("model for minimax must be one of: speech-2.6-turbo, speech-2.6-hd")

    if "volume" in payload and not isinstance(payload.get("volume"), (int, float)):
        fail("volume must be a number")
    if "target_start" in payload and not isinstance(payload.get("target_start"), (int, float)):
        fail("target_start must be a number")
    if "effect_type" in payload:
        if not isinstance(payload.get("effect_type"), str) or not payload.get("effect_type").strip():
            fail("effect_type must be a non-empty string")
        if "effect_params" in payload and not isinstance(payload.get("effect_params"), list):
            fail("effect_params must be an array")


def validate_clone_payload(payload):
    file_url = payload.get("file_url")
    if not isinstance(file_url, str) or not file_url.strip():
        fail("file_url is required")
    if not (file_url.startswith("http://") or file_url.startswith("https://")):
        fail("file_url must start with http:// or https://")
    if "title" in payload and not isinstance(payload.get("title"), str):
        fail("title must be a string")


def validate_assets_payload(payload):
    if "limit" in payload and not isinstance(payload.get("limit"), int):
        fail("limit must be an integer")
    if "offset" in payload and not isinstance(payload.get("offset"), int):
        fail("offset must be an integer")
    provider = payload.get("provider")
    if provider is not None and provider not in {"fish", "minimax"}:
        fail("provider must be one of: fish, minimax")


def request_post(url, req_payload):
    if not API_KEY:
        fail("VECTCUT_API_KEY is required")
    req = urllib.request.Request(
        url=url,
        data=json.dumps(req_payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={"Authorization": f"Bearer {API_KEY}", "Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req) as resp:
            text = resp.read().decode("utf-8", errors="replace")
            status = resp.status
    except urllib.error.HTTPError as e:
        fail(f"HTTP error: {e.code}", {"raw_response": e.read().decode("utf-8", errors="replace")})
    except urllib.error.URLError as e:
        fail("Network error", {"reason": str(e.reason)})

    if status < 200 or status >= 300:
        fail(f"HTTP non-2xx: {status}", {"raw_response": text})

    try:
        data = json.loads(text)
    except Exception:
        fail("Response is not valid JSON", {"raw_response": text})

    if data.get("success") is False or (isinstance(data.get("error"), str) and data.get("error").strip()):
        fail(data.get("error") or "Business error", data.get("output") if data.get("output") is not None else data)

    return data


def run_generate_speech(payload):
    validate_generate_payload(payload)
    data = request_post(f"{BASE_URL.rstrip('/')}/generate_speech", dict(payload))
    output = data.get("output") if isinstance(data.get("output"), dict) else {}
    if not output.get("audio_url"):
        fail("Missing key field: output.audio_url", {"response": data})
    has_draft_ctx = bool(output.get("draft_id") or output.get("draft_url") or output.get("material_id"))
    if has_draft_ctx and not output.get("material_id"):
        fail("Missing key field: output.material_id", {"response": data})
    print(json.dumps(data, ensure_ascii=False))


def run_fish_clone(payload):
    validate_clone_payload(payload)
    req_payload = {k: v for k, v in payload.items() if k in {"file_url", "title"}}
    data = request_post(f"{CLONE_URL.rstrip('/')}/tts/fish/clone_voice", req_payload)
    if not data.get("voice_id"):
        fail("Missing key field: voice_id", {"response": data})
    print(json.dumps(data, ensure_ascii=False))


def run_voice_assets(payload):
    validate_assets_payload(payload)
    query = {k: payload[k] for k in ["limit", "offset", "provider"] if k in payload}
    qs = urllib.parse.urlencode(query)
    url = f"{CLONE_URL.rstrip('/')}/tts/voice_assets"
    if qs:
        url = f"{url}?{qs}"
    data = request_get(url)
    print(json.dumps(data, ensure_ascii=False))


def main():
    if len(sys.argv) < 3:
        print(f"Usage: {sys.argv[0]} <generate_speech|fish_clone|voice_assets> '<json_payload>'")
        sys.exit(1)
    action = sys.argv[1]
    payload = parse_payload(sys.argv[2])
    if action == "generate_speech":
        run_generate_speech(payload)
        return
    if action == "fish_clone":
        run_fish_clone(payload)
        return
    if action == "voice_assets":
        run_voice_assets(payload)
        return
    print(f"Usage: {sys.argv[0]} <generate_speech|fish_clone|voice_assets> '<json_payload>'")
    sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE_URL = os.getenv("VECTCUT_BASE_URL", "https://open.vectcut.com/cut_jianying")
API_KEY = os.getenv("VECTCUT_API_KEY", "")

ACTION_ENDPOINT = {
    "generate_video": "generate_video",
    "task_status": "task_status",
    "render_wait": "generate_video",
}

def fail(error, output=None):
    print(json.dumps({"success": False, "error": error, "output": output if output is not None else ""}, ensure_ascii=False))
    sys.exit(0)

def parse_payload(raw):
    try:
        data = json.loads(raw)
    except Exception as e:
        fail("Invalid JSON payload", {"payload": raw, "exception": str(e)})
    if not isinstance(data, dict):
        fail("Payload must be a JSON object", {"payload": data})
    return data

def parse_json_response(text):
    try:
        return json.loads(text)
    except Exception:
        fail("Response is not valid JSON", {"raw_response": text})

def request_post(endpoint, payload):
    if not API_KEY:
        fail("VECTCUT_API_KEY is required")
    req = urllib.request.Request(
        url=f"{BASE_URL.rstrip('/')}/{endpoint}",
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={"Authorization": f"Bearer {API_KEY}", "Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req) as resp:
            text = resp.read().decode("utf-8", errors="replace")
            status = resp.status
    except urllib.error.HTTPError as e:
        text = e.read().decode("utf-8", errors="replace")
        fail(f"HTTP error: {e.code}", {"raw_response": text})
    except urllib.error.URLError as e:
        fail("Network error", {"reason": str(e.reason)})
    except Exception as e:
        fail("Request failed", {"exception": str(e)})
    if status < 200 or status >= 300:
        fail(f"HTTP non-2xx: {status}", {"raw_response": text})
    data = parse_json_response(text)
    if not isinstance(data, dict):
        fail("JSON response must be an object", {"response": data})
    if data.get("success") is False or (isinstance(data.get("error"), str) and data.get("error").strip()):
        fail(data.get("error") or "Business error", data.get("output") if data.get("output") is not None else data)
    return data

def ensure_generate_payload(payload):
    draft_id = payload.get("draft_id")
    if not isinstance(draft_id, str) or not draft_id.strip():
        fail("draft_id is required")
    if "resolution" in payload and not isinstance(payload.get("resolution"), str):
        fail("resolution must be a string")
    if "framerate" in payload and not isinstance(payload.get("framerate"), str):
        fail("framerate must be a string")

def ensure_status_payload(payload):
    task_id = payload.get("task_id")
    if not isinstance(task_id, str) or not task_id.strip():
        fail("task_id is required")

def call_generate(payload):
    ensure_generate_payload(payload)
    data = request_post("generate_video", {k: v for k, v in payload.items() if k in {"draft_id", "resolution", "framerate"}})
    output = data.get("output")
    task_id = output.get("task_id") if isinstance(output, dict) else None
    if not task_id:
        fail("Missing key field: output.task_id", {"response": data})
    return data

def call_status(payload):
    ensure_status_payload(payload)
    data = request_post("task_status", {"task_id": payload.get("task_id")})
    output = data.get("output")
    status = output.get("status") if isinstance(output, dict) else None
    if not status:
        fail("Missing key field: output.status", {"response": data})
    return data

def call_render_wait(payload):
    task_id = payload.get("task_id")
    if isinstance(task_id, str) and task_id.strip():
        task_id = task_id.strip()
    else:
        generate_res = call_generate(payload)
        task_id = (generate_res.get("output") or {}).get("task_id")

    max_poll = int(payload.get("max_poll", 30))
    poll_interval = float(payload.get("poll_interval", 2))
    last = None
    for _ in range(max_poll):
        status_res = call_status({"task_id": task_id})
        last = status_res
        output = status_res.get("output") or {}
        status = output.get("status")
        if status == "SUCCESS":
            if not output.get("result"):
                fail("Missing key field: output.result", {"response": status_res})
            print(json.dumps(status_res, ensure_ascii=False))
            return
        if status in {"FAILURE", "FAILED"} or output.get("success") is False:
            fail("Render failed", {"task_id": task_id, "response": status_res})
        time.sleep(poll_interval)
    fail("Render polling timeout", {"task_id": task_id, "last_status": last})

def main():
    if len(sys.argv) < 3:
        print(f"Usage: {sys.argv[0]} <generate_video|task_status|render_wait> '<json_payload>'")
        sys.exit(1)
    action = sys.argv[1]
    payload = parse_payload(sys.argv[2])
    if action not in ACTION_ENDPOINT:
        print(f"Usage: {sys.argv[0]} <generate_video|task_status|render_wait> '<json_payload>'")
        sys.exit(1)
    if action == "generate_video":
        print(json.dumps(call_generate(payload), ensure_ascii=False))
        return
    if action == "task_status":
        print(json.dumps(call_status(payload), ensure_ascii=False))
        return
    call_render_wait(payload)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os
import re
import sys
import urllib.error
import urllib.request
from pathlib import Path

BASE_URL = os.getenv("VECTCUT_BASE_URL", "https://open.vectcut.com/cut_jianying")
API_KEY = os.getenv("VECTCUT_API_KEY", "")
ROOT = Path(__file__).resolve().parents[1]
INTRO_ANIMATION_ENUM = Path(os.getenv("INTRO_ANIMATION_ENUM", str(ROOT / "references/enums/intro_animation_types.json")))
OUTRO_ANIMATION_ENUM = Path(os.getenv("OUTRO_ANIMATION_ENUM", str(ROOT / "references/enums/outro_animation_types.json")))
COMBO_ANIMATION_ENUM = Path(os.getenv("COMBO_ANIMATION_ENUM", str(ROOT / "references/enums/combo_animation_types.json")))
MASK_TYPE_ENUM = Path(os.getenv("MASK_TYPE_ENUM", str(ROOT / "references/enums/mask_types.json")))


ACTION_ENDPOINT = {
    "add_image": "add_image",
    "modify_image": "modify_image",
    "remove_image": "remove_image",
}


def fail(error, output=None, hint=None):
    data = {"success": False, "error": error, "output": output if output is not None else ""}
    if hint:
        data["hint"] = hint
    print(json.dumps(data, ensure_ascii=False))
    sys.exit(0)

def load_enum_names(path: Path):
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return {item.get("name") for item in data.get("items", []) if isinstance(item, dict) and item.get("name")}
    except Exception as e:
        fail(f"Failed to load enum file: {path}", {"exception": str(e)})

def parse_payload(raw):
    try:
        data = json.loads(raw)
    except Exception as e:
        fail("Invalid JSON payload", {"payload": raw, "exception": str(e)})
    if not isinstance(data, dict):
        fail("Payload must be a JSON object", {"payload": data})
    return data


def parse_json_response(raw_text):
    try:
        return json.loads(raw_text)
    except Exception:
        fail("Response is not valid JSON", {"raw_response": raw_text})

def known_error_hint(msg):
    if not msg:
        return None
    if "Unknown intro" in msg or "intro_animation" in msg and "Unknown" in msg:
        return "intro_animation 非法，检查 references/enums/intro_animation_types.json"
    if "Unknown outro" in msg or "outro_animation" in msg and "Unknown" in msg:
        return "outro_animation 非法，检查 references/enums/outro_animation_types.json"
    if "Unknown combo" in msg or "combo_animation" in msg and "Unknown" in msg:
        return "combo_animation 非法，检查 references/enums/combo_animation_types.json"
    if "Unknown mask" in msg or "mask_type" in msg and "Unknown" in msg:
        return "mask_type 非法，检查 references/enums/mask_types.json"
    if "New segment overlaps with existing segment" in msg:
        m = re.search(r"start:\s*(\d+),\s*end:\s*(\d+)", msg)
        if m:
            return f"时间片段冲突(us): start={m.group(1)}, end={m.group(2)}；可更换 track_name 或调整 start/end"
        return "时间片段冲突；可更换 track_name 或调整 start/end"
    return None

def ensure_required_fields(endpoint, payload):
    if endpoint == "add_image":
        if not payload.get("image_url"):
            fail("Missing required fields for add_image: image_url", {"payload": payload})
        return
    if endpoint == "modify_image":
        if not payload.get("draft_id") or not payload.get("material_id"):
            fail("Missing required fields for modify_image: draft_id/material_id", {"payload": payload})
        return
    if endpoint == "remove_image":
        if not payload.get("draft_id") or not payload.get("material_id"):
            fail("Missing required fields for remove_image: draft_id/material_id", {"payload": payload})
        return

def ensure_image_enums_valid(endpoint, payload):
    if endpoint == "remove_image":
        return

    intro_animation = payload.get("intro_animation")
    outro_animation = payload.get("outro_animation")
    combo_animation = payload.get("combo_animation")
    mask_type = payload.get("mask_type")

    if intro_animation:
        names = load_enum_names(INTRO_ANIMATION_ENUM)
        if intro_animation not in names:
            fail(f"Unknown intro animation: {intro_animation}", hint="检查 references/enums/intro_animation_types.json")
    if outro_animation:
        names = load_enum_names(OUTRO_ANIMATION_ENUM)
        if outro_animation not in names:
            fail(f"Unknown outro animation: {outro_animation}", hint="检查 references/enums/outro_animation_types.json")
    if combo_animation:
        names = load_enum_names(COMBO_ANIMATION_ENUM)
        if combo_animation not in names:
            fail(f"Unknown combo animation: {combo_animation}", hint="检查 references/enums/combo_animation_types.json")
    if mask_type:
        names = load_enum_names(MASK_TYPE_ENUM)
        if mask_type not in names:
            fail(f"Unknown mask type: {mask_type}", hint="检查 references/enums/mask_types.json")

def call_api(endpoint, payload):
    if not API_KEY:
        fail("VECTCUT_API_KEY is required")

    ensure_required_fields(endpoint, payload)
    ensure_image_enums_valid(endpoint, payload)

    url = f"{BASE_URL.rstrip('/')}/{endpoint}"
    body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(
        url=url,
        data=body,
        method='POST',
        headers={
            'Authorization': f'Bearer {API_KEY}',
            'Content-Type': 'application/json',
        },
    )

    try:
        with urllib.request.urlopen(req) as resp:
            text = resp.read().decode('utf-8', errors='replace')
            status = resp.status
    except urllib.error.HTTPError as e:
        text = e.read().decode('utf-8', errors='replace')
        fail(f"HTTP error: {e.code}", {"raw_response": text})
    except urllib.error.URLError as e:
        fail("Network error", {"reason": str(e.reason)})
    except Exception as e:
        fail("Request failed", {"exception": str(e)})

    if status < 200 or status >= 300:
        fail(f"HTTP non-2xx: {status}", {"raw_response": text})

